#ifndef KULT_API_H
#define KULT_API_H

#include <stdint.h>

#if defined(_WIN32)
#  define KULT_API __declspec(dllexport)
#elif defined(__GNUC__)
#  define KULT_API __attribute__((visibility("default")))
#else
#  define KULT_API
#endif

#ifdef __cplusplus
extern "C" {
#endif

